using namespace std;
string readAll() {
    string s;
    char buf[1 << 16];
    size_t n;
    while ((n = fread(buf, 1, sizeof buf, stdin)) > 0) s.append(buf, n);
    return s;
}
int main() {
    string data = readAll();
    vector<string> lines;
    size_t start = 0;
    while (true) {
        size_t p = data.find('\n', start);
        if (p == string::npos) { lines.push_back(data.substr(start)); break; }
        lines.push_back(data.substr(start, p - start));
        start = p + 1;
    }
    int n = stoi(lines[0]);
    string out;
    for (int i = 0; i < n; i++) {
        const string &a = lines[1 + 2 * i], &b = lines[2 + 2 * i];
        if (a.size() != b.size()) { out += "-1\n"; continue; }
        long long cnt[256] = {0};
        for (unsigned char c : a) cnt[c]++;
        for (unsigned char c : b) cnt[c]--;
        long long extra = 0;
        for (int c = 0; c < 256; c++) if (cnt[c] > 0) extra += cnt[c];
        out += to_string(extra); out += '\n';
    }
    cout << out;
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        String[] lines = new String(System.in.readAllBytes()).split("\n", -1);
        int n = Integer.parseInt(lines[0].trim());
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String a = lines[1 + 2 * i], b = lines[2 + 2 * i];
            if (a.length() != b.length()) {
                out.append("-1\n");
                continue;
            }
            int[] cnt = new int[65536];
            for (int j = 0; j < a.length(); j++) cnt[a.charAt(j)]++;
            for (int j = 0; j < b.length(); j++) cnt[b.charAt(j)]--;
            long extra = 0;
            for (int c : cnt) if (c > 0) extra += c;
            out.append(extra).append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"bytes"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	lines := bytes.Split(data, []byte("\n"))
	n, _ := strconv.Atoi(string(bytes.TrimSpace(lines[0])))
	for i := 0; i < n; i++ {
		a, b := lines[1+2*i], lines[2+2*i]
		if len(a) != len(b) {
			w.WriteString("-1\n")
			continue
		}
		var cnt [256]int
		for _, c := range a {
			cnt[c]++
		}
		for _, c := range b {
			cnt[c]--
		}
		extra := 0
		for _, c := range cnt {
			if c > 0 {
				extra += c
			}
		}
		w.WriteString(strconv.Itoa(extra) + "\n")
	}
}
